<script setup lang="ts">
import { ref } from 'vue'; import { authApi, ApiError } from '../services/api'; import AppAlert from './AppAlert.vue'
const emit = defineEmits<{ registered: [] }>(); const name = ref(''); const email = ref(''); const password = ref(''); const confirm = ref(''); const loading = ref(false); const error = ref(''); const success = ref(''); const form = ref()
const strong = (v: string) => /(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{10,}/.test(v) || 'Mínimo 10 caracteres, con mayúscula, minúscula y número.'
async function submit() { const result = await form.value.validate(); if (!result.valid || password.value !== confirm.value) { if(password.value !== confirm.value) error.value='Las contraseñas no coinciden.'; return }; loading.value=true; error.value=''; try { await authApi.register({ full_name:name.value, email:email.value, password:password.value }); success.value='Cuenta creada. Ya puedes iniciar sesión.'; emit('registered') } catch(e) { error.value=e instanceof ApiError ? e.message : 'No fue posible crear la cuenta.' } finally { loading.value=false } }
</script>
<template><v-form ref="form" @submit.prevent="submit"><AppAlert v-if="error" :message="error"/><v-alert v-if="success" type="success" variant="tonal" class="mb-4">{{ success }}</v-alert><v-text-field v-model="name" label="Nombre completo" :rules="[v => v?.length >= 3 || 'Escribe tu nombre completo']"/><v-text-field v-model="email" label="Correo electrónico" :rules="[v => /.+@.+\..+/.test(v) || 'Escribe un correo válido']"/><v-text-field v-model="password" type="password" label="Contraseña" :rules="[strong]"/><v-text-field v-model="confirm" type="password" label="Confirmar contraseña" :rules="[v => v === password || 'Las contraseñas no coinciden']"/><v-btn type="submit" color="primary" block :loading="loading">Crear cuenta</v-btn></v-form></template>

